<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Add to the house</title><style>
:root{color-scheme:dark}*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:#080c0a;color:#eceadf;font:15px/1.45 system-ui,sans-serif}main{max-width:560px;margin:auto;padding:24px 20px 50px}a{color:#c8d9a4}h1{font:normal 38px/1.12 Georgia,serif;margin:16px 0}p{color:#bbbfae}fieldset{border:0;padding:0;margin:28px 0 20px}legend{font-size:13px;letter-spacing:.11em;color:#c5d49c;margin-bottom:12px}.choices{display:grid;grid-template-columns:1fr 1fr;gap:10px}.choices label{display:block;padding:18px 13px;background:#18211b;border:1px solid #7d916b;border-radius:8px;cursor:pointer}.choices label:has(input:checked){border-color:#def2b4;background:#29392c;box-shadow:0 0 0 2px #a4c77c55}.choices strong{display:block;font-size:18px}.choices small{color:#b3c0ab}.choices input{accent-color:#c7dc9f}label[for=name],label[for=photo]{display:block;margin:20px 0 7px}input[type=text],input[type=file]{display:block;width:100%;min-height:48px;border:1px solid #7d916b;border-radius:6px;background:#141c16;color:#f0ead8;padding:11px;font:inherit}input[type=file]::file-selector-button{padding:9px;border:1px solid #9db58b;border-radius:4px;background:#253829;color:#fff}#selected{display:block;max-width:100%;max-height:40vh;object-fit:contain;margin:18px auto;border:1px solid #455c47}#selected[hidden]{display:none}button{display:block;width:100%;padding:15px;background:#d7e8b4;color:#192117;border:0;border-radius:6px;font:700 16px system-ui;cursor:pointer;margin-top:24px}button:disabled{opacity:.5;cursor:wait}#status{min-height:24px;margin-top:14px}footer{font-size:12px;color:#a9b5a1;border-top:1px solid #485545;margin-top:30px;padding-top:18px}</style></head><body><main><a href="../">← The house</a><h1>Add a photo</h1><p>One photo makes one new room or one object. A room photo covers only the part you captured; the rest stays dark.</p><form id="add" enctype="multipart/form-data" method="post" action="save.php"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['guild_house_csrf'], ENT_QUOTES)?>"><fieldset><legend>MAKE A</legend><div class="choices"><label><input type="radio" name="kind" value="room" checked> <strong>New room</strong><small>Enter through a new door</small></label><label><input type="radio" name="kind" value="object"> <strong>Object</strong><small>Place in your current room</small></label></div></fieldset><label for="photo">Photo</label><input id="photo" type="file" name="photo" accept="image/jpeg,image/png,image/webp" required><img id="selected" hidden alt="Selected photo preview"><label for="name">Name <small>(optional)</small></label><input id="name" name="name" type="text" maxlength="70" placeholder="Uses the photo filename if left blank"><input type="hidden" name="room" id="room" value="threshold"><input type="hidden" name="lon" id="lon" value="0"><input type="hidden" name="lat" id="lat" value="0"><button id="submit" type="submit">MAKE ROOM</button><p id="status" role="status" aria-live="polite"></p></form><footer>Author access only. Saved photos become part of the public house and may be seen by anyone while the house is open. Photos are uploaded and stored on this server. The photo itself is not a 360° scan or measured depth.</footer></main><script>
const params=new URLSearchParams(location.search),room=document.querySelector('#room'),lon=document.querySelector('#lon'),lat=document.querySelector('#lat'),photo=document.querySelector('#photo'),selected=document.querySelector('#selected'),form=document.querySelector('#add'),button=document.querySelector('#submit'),status=document.querySelector('#status');
room.value=/^[a-z0-9-]{1,70}$/.test(params.get('room')||'')?params.get('room'):'threshold';if(params.get('kind')==='object'){form.querySelector('[value=object]').checked=true;button.textContent='ADD OBJECT'}
for(let [el,key,min,max] of [[lon,'lon',-180,180],[lat,'lat',-80,80]]){let n=Number(params.get(key));el.value=Number.isFinite(n)?Math.max(min,Math.min(max,n)):0}
document.querySelectorAll('[name=kind]').forEach(el=>el.onchange=()=>{button.textContent=document.querySelector('[name=kind]:checked').value==='room'?'MAKE ROOM':'ADD OBJECT'});
let previewURL='';photo.onchange=()=>{if(previewURL)URL.revokeObjectURL(previewURL);let file=photo.files[0];selected.hidden=!file;if(file){previewURL=URL.createObjectURL(file);selected.src=previewURL}};
form.onsubmit=async e=>{e.preventDefault();if(!photo.files.length)return;button.disabled=true;status.textContent='Saving to the house…';try{let body=new FormData(form);let source=photo.files[0];if(!form.elements.name.value.trim())body.set('name',source.name.replace(/\.[^.]+$/,''));
  // Re-encode to remove embedded location metadata and keep upload size bounded.
  let image=await createImageBitmap(source);let canvas=document.createElement('canvas');
  if(body.get('kind')==='room'){
    // A photograph is a patch on a sphere, not a full panorama.
    canvas.width=2048;canvas.height=1024;let ctx=canvas.getContext('2d');ctx.fillStyle='#050605';ctx.fillRect(0,0,2048,1024);
    let scale=Math.min(680/image.width,700/image.height);let w=Math.round(image.width*scale),h=Math.round(image.height*scale);
    ctx.drawImage(image,Math.round((2048-w)/2),Math.round((1024-h)/2),w,h);
  }else{
    let scale=Math.min(1,1600/image.width,1600/image.height);canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);
    canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);
  }image.close();
  let blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.88));if(!blob)throw Error('Could not prepare the photo.');
  body.set('photo',blob,body.get('kind')==='room'?'room-partial.jpg':'object.jpg');
  let r=await fetch('save.php',{method:'POST',body,credentials:'same-origin'});let data=await r.json();if(!r.ok||!data.ok)throw Error(data.error||'The photo was not saved.');status.textContent='Saved to the server. Opening '+(data.kind==='room'?'room':'object')+'…';location.href='../?room='+encodeURIComponent(data.room)+'&added='+encodeURIComponent(data.id)}catch(err){status.textContent=err.message;button.disabled=false}};
</script></body></html>
